const INCOME_CATEGORIES = ["工资", "奖金", "兼职", "投资收益", "红包", "其他收入"];
const EXPENSE_CATEGORIES = ["餐饮", "交通", "购物", "居住", "水电", "通讯", "医疗", "教育", "娱乐", "人情", "其他支出"];
const TYPE_LABEL = { income: "收入", expense: "支出" };

const els = {
  form: app.querySelector('[data-role="entry-form"]'),
  date: app.querySelector('[data-role="input-date"]'),
  typeInputs: Array.from(app.querySelectorAll('[data-role="input-type"]')),
  category: app.querySelector('[data-role="input-category"]'),
  amount: app.querySelector('[data-role="input-amount"]'),
  note: app.querySelector('[data-role="input-note"]'),
  message: app.querySelector('[data-role="form-message"]'),
  resetBtn: app.querySelector('[data-role="reset-entry"]'),
  filterMonth: app.querySelector('[data-role="filter-month"]'),
  statIncome: app.querySelector('[data-role="stat-income"]'),
  statExpense: app.querySelector('[data-role="stat-expense"]'),
  statBalance: app.querySelector('[data-role="stat-balance"]'),
  statCount: app.querySelector('[data-role="stat-count"]'),
  list: app.querySelector('[data-role="record-list"]'),
  listHint: app.querySelector('[data-role="list-hint"]'),
  emptyState: app.querySelector('[data-role="empty-state"]'),
  backdrop: app.querySelector('[data-role="dialog-backdrop"]'),
  dialogText: app.querySelector('[data-role="dialog-text"]'),
  dialogCancel: app.querySelector('[data-role="dialog-cancel"]'),
  dialogConfirm: app.querySelector('[data-role="dialog-confirm"]')
};

let state = { records: [], filterMonth: "all" };
let pendingDeleteId = null;

function pad2(value) {
  return String(value).padStart(2, "0");
}

function todayISO() {
  const now = new Date();
  return `${now.getFullYear()}-${pad2(now.getMonth() + 1)}-${pad2(now.getDate())}`;
}

function normalizeRecord(raw) {
  const source = raw && typeof raw === "object" ? raw : {};
  const type = source.type === "expense" ? "expense" : "income";
  const amount = Number(source.amount);
  return {
    ...source,
    id: typeof source.id === "string" && source.id ? source.id : `rec-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    date: typeof source.date === "string" && /^\d{4}-\d{2}-\d{2}$/.test(source.date) ? source.date : todayISO(),
    type,
    category: typeof source.category === "string" && source.category ? source.category : (type === "income" ? "其他收入" : "其他支出"),
    amount: Number.isFinite(amount) ? amount : 0,
    note: typeof source.note === "string" ? source.note : ""
  };
}

function normalizeState(raw) {
  const source = raw && typeof raw === "object" ? raw : {};
  const records = Array.isArray(source.records) ? source.records.map(normalizeRecord) : [];
  const filterMonth = typeof source.filterMonth === "string" && source.filterMonth ? source.filterMonth : "all";
  return { ...source, records, filterMonth };
}

function formatMoney(value) {
  const num = Number.isFinite(value) ? value : 0;
  const sign = num < 0 ? "-" : "";
  return `${sign}¥${Math.abs(num).toFixed(2)}`;
}

function monthOf(dateStr) {
  return typeof dateStr === "string" ? dateStr.slice(0, 7) : "";
}

function monthLabel(monthKey) {
  const parts = monthKey.split("-");
  if (parts.length !== 2) return monthKey;
  return `${parts[0]}年${Number(parts[1])}月`;
}

function currentCategories(type) {
  return type === "expense" ? EXPENSE_CATEGORIES : INCOME_CATEGORIES;
}

function selectedType() {
  const checked = els.typeInputs.find((input) => input.checked);
  return checked && checked.value === "expense" ? "expense" : "income";
}

function fillCategoryOptions(type, keepValue) {
  const options = currentCategories(type);
  const previous = keepValue || els.category.value;
  els.category.textContent = "";
  options.forEach((name) => {
    const option = document.createElement("option");
    option.value = name;
    option.textContent = name;
    els.category.appendChild(option);
  });
  if (options.includes(previous)) {
    els.category.value = previous;
  }
}

function setMessage(text, tone) {
  els.message.textContent = text || "";
  if (tone) {
    els.message.setAttribute("data-tone", tone);
  } else {
    els.message.removeAttribute("data-tone");
  }
}

function availableMonths(records) {
  const set = new Set();
  records.forEach((record) => {
    const key = monthOf(record.date);
    if (key) set.add(key);
  });
  return Array.from(set).sort((a, b) => b.localeCompare(a));
}

function renderFilterOptions() {
  const months = availableMonths(state.records);
  const wanted = state.filterMonth;
  els.filterMonth.textContent = "";

  const allOption = document.createElement("option");
  allOption.value = "all";
  allOption.textContent = "全部月份";
  els.filterMonth.appendChild(allOption);

  months.forEach((key) => {
    const option = document.createElement("option");
    option.value = key;
    option.textContent = monthLabel(key);
    els.filterMonth.appendChild(option);
  });

  const valid = wanted === "all" || months.includes(wanted);
  state.filterMonth = valid ? wanted : "all";
  els.filterMonth.value = state.filterMonth;
}

function visibleRecords() {
  if (state.filterMonth === "all") return state.records.slice();
  return state.records.filter((record) => monthOf(record.date) === state.filterMonth);
}

function computeTotals(records) {
  let income = 0;
  let expense = 0;
  records.forEach((record) => {
    const amount = Number.isFinite(record.amount) ? record.amount : 0;
    if (record.type === "expense") {
      expense += amount;
    } else {
      income += amount;
    }
  });
  return { income, expense, balance: income - expense, count: records.length };
}

function renderStats(records) {
  const totals = computeTotals(records);
  els.statIncome.textContent = formatMoney(totals.income);
  els.statExpense.textContent = formatMoney(totals.expense);
  els.statBalance.textContent = formatMoney(totals.balance);
  els.statCount.textContent = String(totals.count);
}

function buildRecordItem(record) {
  const item = document.createElement("li");
  item.className = `record record--${record.type}`;
  item.setAttribute("data-record-id", record.id);

  const date = document.createElement("span");
  date.className = "record__date";
  date.textContent = record.date;

  const main = document.createElement("div");
  main.className = "record__main";

  const category = document.createElement("span");
  category.className = "record__category";
  const categoryText = document.createElement("span");
  categoryText.textContent = record.category;
  const tag = document.createElement("span");
  tag.className = `record__tag record__tag--${record.type}`;
  tag.textContent = TYPE_LABEL[record.type];
  category.appendChild(categoryText);
  category.appendChild(tag);
  main.appendChild(category);

  if (record.note) {
    const note = document.createElement("span");
    note.className = "record__note";
    note.textContent = record.note;
    main.appendChild(note);
  }

  const amount = document.createElement("span");
  amount.className = `record__amount record__amount--${record.type}`;
  amount.textContent = `${record.type === "income" ? "+" : "-"}${formatMoney(record.amount)}`;

  const action = document.createElement("div");
  action.className = "record__action";
  const deleteBtn = document.createElement("button");
  deleteBtn.type = "button";
  deleteBtn.className = "btn btn--ghost btn--small";
  deleteBtn.setAttribute("data-role", "delete-record");
  deleteBtn.setAttribute("data-record-id", record.id);
  deleteBtn.textContent = "删除";
  action.appendChild(deleteBtn);

  item.appendChild(date);
  item.appendChild(main);
  item.appendChild(amount);
  item.appendChild(action);
  return item;
}

function renderList(records) {
  els.list.textContent = "";
  const sorted = records.slice().sort((a, b) => {
    if (a.date === b.date) return 0;
    return a.date < b.date ? 1 : -1;
  });

  sorted.forEach((record) => {
    els.list.appendChild(buildRecordItem(record));
  });

  els.emptyState.hidden = sorted.length > 0;
  if (sorted.length === 0) {
    els.emptyState.textContent =
      state.records.length === 0 ? "暂无记录，先在上方添加一笔吧。" : "当前筛选月份下没有记录。";
  }

  const scope = state.filterMonth === "all" ? "全部月份" : monthLabel(state.filterMonth);
  els.listHint.textContent = `${scope} · 共 ${sorted.length} 条`;
}

function render() {
  renderFilterOptions();
  const records = visibleRecords();
  renderStats(records);
  renderList(records);
}

async function persist(nextState) {
  const merged = { ...state, ...nextState };
  try {
    await appStore.setState(merged);
    state = normalizeState(merged);
    return true;
  } catch (error) {
    setMessage("保存失败，请重试。当前输入已保留。", "error");
    return false;
  }
}

function openDeleteDialog(record) {
  pendingDeleteId = record.id;
  els.dialogText.textContent = `确定删除 ${record.date} 的${TYPE_LABEL[record.type]}记录「${record.category} ${formatMoney(
    record.amount
  )}」吗？此操作不可撤销。`;
  els.backdrop.hidden = false;
  els.dialogConfirm.focus();
}

function closeDeleteDialog() {
  pendingDeleteId = null;
  els.backdrop.hidden = true;
}

async function confirmDelete() {
  const id = pendingDeleteId;
  closeDeleteDialog();
  if (!id) return;
  const nextRecords = state.records.filter((record) => record.id !== id);
  const ok = await persist({ records: nextRecords });
  if (ok) {
    setMessage("记录已删除。", "success");
    render();
  }
}

function readForm() {
  const type = selectedType();
  const date = els.date.value;
  const category = els.category.value;
  const amountRaw = els.amount.value.trim();
  const note = els.note.value.trim();

  if (!date) return { error: "请选择日期。" };
  if (!category) return { error: "请选择分类。" };
  if (!amountRaw) return { error: "请输入金额。" };
  const amount = Number(amountRaw);
  if (!Number.isFinite(amount) || amount <= 0) return { error: "金额需为大于 0 的数字。" };

  return {
    record: {
      id: `rec-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      date,
      type,
      category,
      amount: Math.round(amount * 100) / 100,
      note
    }
  };
}

async function handleSubmit(event) {
  event.preventDefault();
  const result = readForm();
  if (result.error) {
    setMessage(result.error, "error");
    return;
  }

  const nextRecords = state.records.concat(result.record);
  const ok = await persist({ records: nextRecords });
  if (!ok) return;

  setMessage(`已添加：${TYPE_LABEL[result.record.type]} ${result.record.category} ${formatMoney(result.record.amount)}`, "success");
  els.amount.value = "";
  els.note.value = "";
  els.date.value = todayISO();
  render();
}

function handleReset() {
  els.date.value = todayISO();
  els.amount.value = "";
  els.note.value = "";
  fillCategoryOptions(selectedType(), "");
  setMessage("");
}

async function handleFilterChange() {
  const value = els.filterMonth.value;
  const ok = await persist({ filterMonth: value });
  if (!ok) {
    els.filterMonth.value = state.filterMonth;
    return;
  }
  render();
}

function bindEvents() {
  els.form.addEventListener("submit", handleSubmit);
  els.resetBtn.addEventListener("click", (event) => {
    event.preventDefault();
    handleReset();
  });

  els.typeInputs.forEach((input) => {
    input.addEventListener("change", () => {
      fillCategoryOptions(selectedType(), "");
    });
  });

  els.filterMonth.addEventListener("change", handleFilterChange);

  els.list.addEventListener("click", (event) => {
    const target = event.target;
    if (!(target instanceof Element)) return;
    const button = target.closest('[data-role="delete-record"]');
    if (!button) return;
    const id = button.getAttribute("data-record-id");
    const record = state.records.find((item) => item.id === id);
    if (record) openDeleteDialog(record);
  });

  els.dialogCancel.addEventListener("click", closeDeleteDialog);
  els.dialogConfirm.addEventListener("click", confirmDelete);
  els.backdrop.addEventListener("click", (event) => {
    if (event.target === els.backdrop) closeDeleteDialog();
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && !els.backdrop.hidden) closeDeleteDialog();
  });
}

async function init() {
  const raw = await appStore.getState();
  state = normalizeState(raw);
  if (!Array.isArray(raw && raw.records)) {
    await appStore.setState({ ...state, records: [] });
  }
  els.date.value = todayISO();
  fillCategoryOptions("income", "");
  bindEvents();
  render();
}

await init();

artifact.css:
:root {
  --bg: #0f172a;
  --bg-soft: #16213c;
  --surface: #1c2942;
  --surface-2: #223252;
  --border: #33456b;
  --text: #eef3ff;
  --text-muted: #9fb0d0;
  --accent: #4f8cff;
  --accent-strong: #2f6fe4;
  --income: #35d39a;
  --expense: #ff7a8a;
  --danger: #e5484d;
  --radius: 14px;
  --shadow: 0 18px 40px rgba(4, 10, 24, 0.45);
}

#app {
  min-height: 100vh;
  background:
    radial-gradient(1100px 620px at 12% -10%, #1d2f57 0%, rgba(29, 47, 87, 0) 62%),
    radial-gradient(900px 520px at 100% 0%, #23375f 0%, rgba(35, 55, 95, 0) 58%),
    var(--bg);
  color: var(--text);
  font-family: "PingFang SC", "Microsoft YaHei", "Hiragino Sans GB", system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 15px;
  line-height: 1.6;
  padding: 28px 18px 56px;
  box-sizing: border-box;
}

#app *,
#app *::before,
#app *::after {
  box-sizing: border-box;
}

.ledger {
  width: 100%;
  max-width: 940px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.ledger__header {
  padding: 6px 4px 0;
}

.ledger__title {
  margin: 0;
  font-size: 26px;
  letter-spacing: 0.5px;
  color: var(--text);
}

.ledger__subtitle {
  margin: 6px 0 0;
  color: var(--text-muted);
  font-size: 13.5px;
}

.panel {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 20px;
}

.panel__head {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 16px;
}

.panel__title {
  margin: 0 0 14px;
  font-size: 17px;
  color: var(--text);
}

.panel__head .panel__title {
  margin-bottom: 0;
}

.panel__hint {
  color: var(--text-muted);
  font-size: 13px;
}

.entry-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px 16px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}

.field--wide {
  grid-column: 1 / -1;
}

.field--inline {
  flex-direction: row;
  align-items: center;
  gap: 10px;
}

.field__label {
  font-size: 13px;
  color: var(--text-muted);
  letter-spacing: 0.3px;
}

.field__control {
  width: 100%;
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: var(--surface-2);
  color: var(--text);
  font-size: 14.5px;
  font-family: inherit;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.field__control::placeholder {
  color: #7d8db0;
}

.field__control:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(79, 140, 255, 0.25);
}

select.field__control {
  appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, var(--text-muted) 50%),
    linear-gradient(135deg, var(--text-muted) 50%, transparent 50%);
  background-position: calc(100% - 18px) 50%, calc(100% - 13px) 50%;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
  padding-right: 34px;
}

.field--inline .field__control {
  width: auto;
  min-width: 168px;
}

.segmented {
  display: inline-flex;
  gap: 6px;
  padding: 4px;
  border-radius: 10px;
  background: var(--surface-2);
  border: 1px solid var(--border);
}

.segmented__item {
  position: relative;
  display: inline-flex;
  align-items: center;
  cursor: pointer;
}

.segmented__item input {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
}

.segmented__text {
  display: inline-block;
  padding: 7px 20px;
  border-radius: 8px;
  font-size: 14px;
  color: var(--text-muted);
  transition: background 0.15s ease, color 0.15s ease;
}

.segmented__item input:checked + .segmented__text {
  background: var(--accent);
  color: #fff;
}

.segmented__item input:focus-visible + .segmented__text {
  box-shadow: 0 0 0 3px rgba(79, 140, 255, 0.35);
}

.form-actions {
  grid-column: 1 / -1;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 2px;
}

.btn {
  border: 1px solid transparent;
  border-radius: 10px;
  padding: 10px 20px;
  font-size: 14.5px;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease, transform 0.1s ease;
}

.btn:active {
  transform: translateY(1px);
}

.btn--primary {
  background: var(--accent);
  color: #fff;
}

.btn--primary:hover {
  background: var(--accent-strong);
}

.btn--ghost {
  background: transparent;
  border-color: var(--border);
  color: var(--text-muted);
}

.btn--ghost:hover {
  color: var(--text);
  border-color: var(--accent);
}

.btn--danger {
  background: var(--danger);
  color: #fff;
}

.btn--danger:hover {
  background: #c93b40;
}

.btn--small {
  padding: 6px 12px;
  font-size: 13px;
  border-radius: 8px;
}

.form-message {
  grid-column: 1 / -1;
  margin: 0;
  min-height: 20px;
  font-size: 13.5px;
  color: var(--text-muted);
}

.form-message[data-tone="error"] {
  color: var(--expense);
}

.form-message[data-tone="success"] {
  color: var(--income);
}

.stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.stat {
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat__label {
  font-size: 12.5px;
  color: var(--text-muted);
}

.stat__value {
  font-size: 20px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--text);
}

.stat--income .stat__value {
  color: var(--income);
}

.stat--expense .stat__value {
  color: var(--expense);
}

.stat--balance .stat__value {
  color: var(--accent);
}

.record-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.record {
  display: grid;
  grid-template-columns: 96px 1fr auto auto;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-left: 3px solid var(--accent);
  border-radius: 12px;
}

.record--income {
  border-left-color: var(--income);
}

.record--expense {
  border-left-color: var(--expense);
}

.record__date {
  font-size: 13px;
  color: var(--text-muted);
  font-variant-numeric: tabular-nums;
}

.record__main {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.record__category {
  font-size: 14.5px;
  color: var(--text);
  display: flex;
  align-items: center;
  gap: 8px;
}

.record__tag {
  font-size: 11.5px;
  padding: 1px 8px;
  border-radius: 999px;
  border: 1px solid var(--border);
  color: var(--text-muted);
}

.record__tag--income {
  color: var(--income);
  border-color: rgba(53, 211, 154, 0.5);
}

.record__tag--expense {
  color: var(--expense);
  border-color: rgba(255, 122, 138, 0.5);
}

.record__note {
  font-size: 13px;
  color: var(--text-muted);
  overflow-wrap: anywhere;
}

.record__amount {
  font-size: 16px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.record__amount--income {
  color: var(--income);
}

.record__amount--expense {
  color: var(--expense);
}

.empty-state {
  margin: 4px 0 0;
  padding: 22px;
  text-align: center;
  color: var(--text-muted);
  font-size: 14px;
  border: 1px dashed var(--border);
  border-radius: 12px;
}

.dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(6, 12, 26, 0.68);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 40;
}

.dialog-backdrop[hidden] {
  display: none;
}

.dialog {
  width: 100%;
  max-width: 380px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 22px;
}

.dialog__title {
  margin: 0 0 10px;
  font-size: 17px;
  color: var(--text);
}

.dialog__text {
  margin: 0 0 18px;
  font-size: 14px;
  color: var(--text-muted);
  overflow-wrap: anywhere;
}

.dialog__actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

@media (max-width: 720px) {
  .entry-form {
    grid-template-columns: minmax(0, 1fr);
  }

  .stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .record {
    grid-template-columns: 1fr auto;
    grid-template-areas:
      "date amount"
      "main main"
      "action action";
    row-gap: 8px;
  }

  .record__date {
    grid-area: date;
  }

  .record__main {
    grid-area: main;
  }

  .record__amount {
    grid-area: amount;
    text-align: right;
  }

  .record__action {
    grid-area: action;
    justify-self: end;
  }
